<template>
  <q-page :class="['deployment-status-page', 'q-pa-md', { 'monitor-mode': monitorMode }]">
    <!-- ══ Header ══ -->
    <div class="header-row row items-start justify-between q-col-gutter-md q-mb-md">
      <div class="col-12 col-md">
        <div class="row items-center q-gutter-sm">
          <h4 class="page-title q-my-none">Deployment Status</h4>
          <!-- Environment/branch pill is desk-only. The wall header shows just
