          <span v-if="refreshing" class="refresh-hint">
            <q-spinner size="11px" class="q-mr-xs" />refreshing
          </span>
          <span v-else class="refresh-hint">
            · auto-refreshes every {{ autoRefreshMinutes }} min
          </span>
        </div>
      </div>

      <div v-if="!monitorMode" class="col-12 col-md-auto row items-center q-gutter-sm justify-end">
