<script lang="ts">
import { defineComponent } from 'vue';
import { date } from 'quasar';
import type { QTableColumn } from 'quasar';
import {
  DEFAULT_TRACK,
  DEPLOYMENT_STATE_PRESENTATION,
  GATE_STATE_PRESENTATION,
  METRIC_WINDOW,
  RELEASE_TRACKS,
  STOPPED_DEPLOYMENT_STATES,
  DEPLOY_STAGE_REASON,
  blockedByClasses,
  deployBlockingTestsPrometheusService,
  deploymentRank,
  rowTone,
  stoppedRows,
  deploymentState,
  deriveTrackRows,
  gateRank,
  gateState,
  monitorQualifier,
  runUrl,
  serviceDisplayName,
  serviceWebKey,
  trackLabel,
  trackReportCounts,
  type BlockingGateState,
  type DeploymentState,
  type GateStatePresentation,
  type GateTone,
  type ReleaseTrack,
  type ServiceBlockingStatus,
} from 'src/services/tests';
import { logger } from 'src/utils/logger';

/**
 * How often the page re-queries Prometheus on its own — desk and wall alike.
 *
 * Tied to how often the DATA can change, which is a deploy, not to how often the
 * wall changes what it shows. Those used to be the same timer; see
 * LINE_ROTATION_MS for why they no longer are.
 */
export const AUTO_REFRESH_MS = 5 * 60 * 1000;

/**
 * How often the wall flips between VESTA and NOVA.
 *
 * DELIBERATELY DECOUPLED FROM THE FETCH. It used to be the same 5-minute timer:
 * every tick flipped the line and refetched, which was tidy while the two
 * cadences agreed. At 30 seconds they cannot — that would be ten Prometheus
 * queries a minute, forever, for data that only changes when something deploys.
 *
 * Nothing is lost by separating them, because ONE query already answers both
 * lines: getBlockingStatuses() is called without a track, so `reported` holds
 * VESTA and NOVA together and deriveTrackRows() picks the line to render. A
 * rotation is therefore a pure re-render of data the page already has — no I/O,
 * no spinner, no chance of a switch stalling on the network.
 */
export const LINE_ROTATION_MS = 30 * 1000;

/**
 * Retry backoff after a failed monitor fetch — doubling from the first value and
 * held at the last. Bounded on purpose: the wall runs for weeks without a
 * reload, so an open-ended backoff would eventually wait hours between attempts.
 * It never gives up and there is no attempt limit — a kiosk has nobody to press
 * "try again".
 */
export const RETRY_BACKOFF_MS = [10_000, 20_000, 40_000, 60_000] as const;

/**
 * When the data on the wall stops being presented as current — twice the FETCH
 * cycle, so one missed refresh is not called stale but a real stall is. Keyed to
 * the fetch and not to the rotation: a rotation renders data it already has, so
 * it says nothing about how current that data is.
 * Only ever a word and a colour beside the age, never a modal.
 */
export const STALE_AFTER_MS = 2 * AUTO_REFRESH_MS;

/**
 * Label, icon and hover explanation per gate state.
 *
 * Now sourced from GATE_STATE_PRESENTATION so the desk page and the TV monitor
 * view cannot disagree about what a state is called — the wording below is
 * unchanged, it simply has one definition instead of two. The shared map also
 * carries a `tvLabel` and a `tone`, which this page has no use for and ignores.
 *
 * Purely presentational: the ORDER these states carry lives in GATE_ORDER in
 * the service, so the board's default grouping and the Gate status column's
 * sort cannot drift apart from each other.
 */
const GATE_STATES: Record<BlockingGateState, GateStatePresentation> = GATE_STATE_PRESENTATION;

/**
 * The same, for the second column. Shared with the wall for the same reason:
 * the desk and the monitor must not disagree about what "Not deployed" means.
 */
const DEPLOYMENT_STATES: Record<DeploymentState, GateStatePresentation> =
  DEPLOYMENT_STATE_PRESENTATION;

/**
 * KPI tiles. Each tile filters the table to the states it counts — so the
 * "Unverified" tile, which rolls up two states, filters to both.
 *
 * There is deliberately no age tile. A "Stale" tile counted verdicts older than
 * 24h as a problem, which for a fleet where several services deploy weekly meant
 * a permanent non-zero count describing nothing wrong. Age now lives in the
 * Reported column, next to each verdict, where it is a fact about one row rather
 * than a fleet-wide alarm.
 */
const KPI_TILES: {
  label: string;
  icon: string;
  hint: string;
  states: BlockingGateState[];
}[] = [
  { label: 'Blocking deploys', icon: 'block', hint: 'gate reported failure', states: ['failing'] },
  { label: 'Green', icon: 'verified', hint: 'blocking tests all passed', states: ['passing'] },
  {
    label: 'No blocking tests',
    icon: 'help_outline',
    hint: 'green, but nothing ran',
    states: ['no-tests'],
  },
  {
    label: 'Unverified',
    icon: 'help_center',
    hint: 'no verdict for this run',
    states: ['did-not-run', 'incomplete'],
  },
  // The "No gate metric" tile (states: no-metrics / not-configured) was removed
  // per DOCB-14017: a service with no metric is not a headline number worth its
  // own summary field. The states themselves are unchanged in the model, and
  // no-metric rows still reach the table behind the "show services without
  // metrics" toggle — only the KPI tile is gone.
];

type KpiTile = (typeof KPI_TILES)[number];

export default defineComponent({
  name: 'DeploymentStatusPage',

  data() {
    return {
      /**
       * Every row Prometheus returned, both release lines together. One request
       * covers both, so switching track is a filter rather than a refetch — and
       * it is the only way the page can say that a track reports nothing at all.
       */
      reported: [] as ServiceBlockingStatus[],
      /** Release line on show. VESTA first: it is the line that ships today. */
      track: DEFAULT_TRACK,
      loading: false,
      /** Background refresh in flight — deliberately separate from `loading`, which swaps the table out */
      refreshing: false,
      refreshTimer: null as number | null,
      error: null as string | null,
      lastFetchedAt: null as Date | null,
      // ── Monitor-mode (kiosk) state. Inert on the desk. ──
      /** A monitor fetch failed and a retry is armed. Shown as a word, never a dialog. */
      retrying: false,
      /** Index into RETRY_BACKOFF_MS; reset to 0 by any success. */
      retryStep: 0,
      retryTimer: null as number | null,
      /**
       * The line rotation is re-armed once per cycle rather than as a repeating
       * interval, so each deadline is measured from the wall clock and cannot
       * accumulate drift over thousands of cycles. See scheduleSwitch().
       */
      switchTimer: null as number | null,
      /** Ticks the live age readout without a second data source. Monitor only. */
      now: Date.now(),
      clockTimer: null as number | null,
      search: '' as string | null,
      showUnreported: true,
      stateFilter: null as KpiTile | null,
      flashed: null as string | null,
      /**
       * `sortBy: null` is the board's own default order, not the absence of one.
       * QTable renders rows exactly as given while no column is sorted, so the
       * order set by sortForBoard() — attention first, then blocking test-case
       * count descending — is what a reader sees on arrival. Clicking any header
       * hands sorting to QTable, and its third click returns here.
       */
      pagination: { rowsPerPage: 30, sortBy: null as string | null, descending: false },
    };
  },

  computed: {
    /**
     * The environment this dashboard reports on. Not user-selectable: the page
     * always shows the estate for the deployment it is running in. Both
     * deployment workflows fail the build when APP_VUE_STAGE is empty, so it is
     * always set here.
     */
    environment(): string {
      /**
       * The one environment this board describes.
       *
       * Defaulted rather than passed through raw, and that default is
       * load-bearing: an empty value means seriesSelector() omits the
       * `environment` matcher entirely, so the page reads EVERY environment at
       * once. Most services only report from `dev`, so that stayed invisible —
       * but the web app reports from dev, stage, sandbox and prod, and its four
       * legitimate rows read as duplicates of one service, three of them with no
       * version because a blocked run publishes no image tag.
       *
       * quasar.config.cjs now defaults the injected value too; this is the
       * guard at the point where the query is actually built.
       *
       * `local` maps to `dev` the same way every sibling Tests page does
       * (TestsPage, TestsOverviewPage, TestDetailsPage, StatisticsDashboard).
       * It is an explicit opt-in for running against local APIs, never a
       * default — but no service ever reports FROM it, so querying it verbatim
       * would leave a local dev staring at an empty board.
       */
      const stage = process.env.APP_VUE_STAGE || 'dev';
      return stage === 'local' ? 'dev' : stage;
    },

    autoRefreshMinutes(): number {
      return Math.round(AUTO_REFRESH_MS / 60_000);
    },

    metricWindow(): string {
      return METRIC_WINDOW;
    },

    /**
     * Whether this render is the wall/kiosk view rather than the desk page.
     *
     * Driven by the route's `meta.monitor` flag, so the same component serves
     * both /tests/deployment-status (desk) and /tests/deployment-status-monitor
     * (wall). Monitor mode strips every interactive control, enlarges the type,
     * rotates the release line on a timer, and drops the no-metric rows a wall
     * should not carry — all off this one flag.
     */
    monitorMode(): boolean {
      return Boolean(this.$route?.meta?.monitor);
    },

    /**
     * The honest tally under the wall headline: "1 never ran · 1 cancelled —
     * unverified, not passing", or null when every visible row carries a real
     * verdict. Computed from the rows actually on screen. Desk mode never shows
     * it.
     */
    monitorQualifierText(): string | null {
      if (!this.monitorMode) return null;
      return monitorQualifier(this.visibleStatuses);
    },

    /** Age of the data on screen, in words. Monitor only. */
    dataAgeText(): string {
      if (this.lastFetchedAt === null) return 'loading…';
      const seconds = Math.max(0, Math.round((this.now - this.lastFetchedAt.getTime()) / 1000));
      if (seconds < 60) return 'updated just now';
      const minutes = Math.round(seconds / 60);
      if (minutes < 60) return `updated ${minutes}m ago`;
      const hours = Math.round(minutes / 60);
      if (hours < 24) return `updated ${hours}h ago`;
      return `updated ${Math.round(hours / 24)}d ago`;
    },

    /** Whether the data on the wall is well past a cycle old. Monitor only. */
    dataIsStale(): boolean {
      if (this.lastFetchedAt === null) return false;
      return this.now - this.lastFetchedAt.getTime() > STALE_AFTER_MS;
    },

    /**
     * The table's rows: the selected track's verdicts, plus a placeholder for
     * every service in the app's registry that this track is silent about.
     *
     * Narrowing to one track BEFORE the merge is what makes the placeholders
     * mean anything. mergeWithKnownServices keys coverage on the service name
     * alone, so handed both lines at once it would treat a VESTA-only reporter as
     * covered and quietly swallow the missing NOVA verdict.
     *
     * Comes back in the board's default order (sortForBoard) — the filters below
     * preserve it, and QTable renders it as given until a header is clicked.
     */
    statuses(): ServiceBlockingStatus[] {
      return deriveTrackRows(this.reported, this.track, this.environment);
    },

    /** Services actually reporting per track — never placeholders. */
    reportsPerTrack(): Record<ReleaseTrack, number> {
      return trackReportCounts(this.reported);
    },

    /** How many services report on the selected track. Zero is a fact, not a fault. */
    trackReports(): number {
      return this.reportsPerTrack[this.track];
    },

    /** The selected line, named by its branch so it cannot be read as a channel. */
    trackText(): string {
      return trackLabel(this.track, this.environment);
    },

    /**
     * The header badge text.
     *
     * Desk: the full branch-line label ("VESTA (dev)") — the precise form that
     * disambiguates a track from the app's identically-named release channels.
     * Wall: just the bare track word ("VESTA" / "NOVA"), upper-case. A across-the
     * room overview wants the one word, not the branch/env qualifier — the
     * environment is fixed for the panel and stated nowhere it could mislead.
     */
    badgeText(): string {
      return this.monitorMode ? this.track.toUpperCase() : this.trackText;
    },

    /**
     * The track switch, each option carrying how many services report on it — so
     * a line nothing publishes for is visible before it is selected, rather than
     * looking like an empty board once it is.
     *
     * Labelled `VESTA (dev) · 12`, not `VESTA · 12`: the branch is the part that
     * says which line this is, since the app's release channels carry the same two
     * names for the opposite thing. See trackLabel().
     */
    trackOptions(): { label: string; value: ReleaseTrack }[] {
      return RELEASE_TRACKS.map((value) => ({
        label: `${trackLabel(value, this.environment)} · ${this.reportsPerTrack[value]}`,
        value,
      }));
    },

    environmentColor(): string {
      const colorMap: Record<string, string> = {
        dev: '#2563eb',
        stage: '#f59e0b',
        prod: '#dc2626',
        demo: '#9333ea',
        sandbox: '#0d9488',
      };
      return colorMap[this.environment] || '#64748b';
    },

    columns(): QTableColumn<ServiceBlockingStatus>[] {
      return [
        {
          name: 'service',
          label: 'Service',
          field: (row) => serviceDisplayName(row.service),
          align: 'left',
          sortable: true,
        },
        {
          name: 'status',
          // "Test status", not "Gate status": this column now answers only the
          // test half of the question. The deploy half is the column beside it.
          label: 'Test status',
          // Sorted by the service's own state ranking, so this column and the
          // board's tie-break cannot disagree about what comes first.
          field: (row) => gateRank(gateState(row)),
          align: 'left',
          sortable: true,
        },
        {
          // Directly beside Test status, and deliberately NOT derived from it:
          // the gate is decided before Helm runs, so a service can pass every
          // test and still fail to roll out (auth-service, blocked at git
          // tagging with 130 tests green). See deploymentState().
          name: 'deployment',
          label: 'Deployment status',
          field: (row) => deploymentRank(deploymentState(row)),
          align: 'left',
          sortable: true,
        },
        {
          // Sits next to the verdict on purpose: a verdict without its age is not
          // a status. Sortable, so "what has not reported lately" is one click
          // away — without any row being called stale for it.
          name: 'lastRun',
          label: 'Reported',
          field: (row) => row.finishedAt.getTime(),
          align: 'left',
          sortable: true,
        },
        { name: 'failed', label: 'Failed', field: (row) => row.counts.failed, align: 'right', sortable: true },
        {
          // On the wall as well as the desk (Gregor's call): the team wants the
          // magnitude visible in the room. Seven columns is tight on a 1080p
          // panel, and what buys the width is the type scale below — a passing
          // row is no longer bold and renders a step smaller, so the board is
          // dominated by the rows that need attention rather than by all of them.
          //
          // "Blocking" is not decoration: these are the cases that can stop a
          // deployment, not the service's whole suite. It is explicitly NOT a
          // quality ranking — ocr-service reporting 1 is not worse than doc2-api
          // reporting 14,296 — which is why the default order no longer runs on
          // it (see sortForBoard).
          name: 'totalTests',
          label: 'Blocking cases',
          field: 'totalTests',
          align: 'right',
          sortable: true,
        },
        {
          // "Version" on the wall, "Build" on the desk: the wall shows the image
          // tag alone (see the cell), the desk adds the commit chip.
          name: 'build',
          label: this.monitorMode ? 'Version' : 'Build',
          field: 'imageTag',
          align: 'left',
          sortable: false,
        },
        // The per-row Actions column (CI run / full results links) is desk-only —
        // there is nothing to click on a wall.
        ...(this.monitorMode
          ? []
          : ([
              { name: 'actions', label: '', field: 'service', align: 'right', sortable: false },
            ] as QTableColumn<ServiceBlockingStatus>[])),
      ];
    },

    /**
     * Whether the READER hid the rows, as opposed to nobody publishing any.
     *
     * The empty board branches on this rather than on `statuses.length`, which
     * is never 0: mergeWithKnownServices seeds a placeholder row for every known
     * service, so an environment that reports nothing still arrives here with a
     * full set of no-metric rows. Counting them would have told a wall showing
     * nothing that its rows were "filtered out" by filters nobody had set.
     */
    filtersActive(): boolean {
      return Boolean((this.search || '').trim()) || this.stateFilter !== null;
    },

    /** Services that actually published something, as opposed to placeholders. */
    reportingCount(): number {
      return this.statuses.filter((status) => status.hasMetrics).length;
    },

    visibleStatuses(): ServiceBlockingStatus[] {
      const term = (this.search || '').trim().toLowerCase();

      return this.statuses.filter((status) => {
        // A wall display should not carry rows that have no data at all: the
        // no-metric services are dropped from the monitor entirely (DOCB-14017).
        // The state stays in the model — it is simply not shown here.
        if (this.monitorMode && this.state(status) === 'no-metrics') return false;
        if (!this.showUnreported && !status.hasMetrics) return false;
        if (this.stateFilter && !this.stateFilter.states.includes(this.state(status)))
          return false;
        if (term) {
          const haystack =
            `${status.service} ${this.displayName(status.service)} ${status.repo ?? ''}`.toLowerCase();
          if (!haystack.includes(term)) return false;
        }
        return true;
      });
    },

    /**
     * The rows where nothing is getting deployed — EITHER column.
     *
     * Was the test-failing rows alone, which is how the banner came to read "No
     * service is failing" in green directly above a red FAILED row: a service
     * with passing tests and a failed rollout was invisible to it. An all-clear
     * that contradicts the table beneath it is worse than no banner.
     *
     * Shares stoppedRows() with the monitor headline and the per-row indicator,
     * so the three cannot disagree about which rows are the alarming ones.
     */
    stoppedStatuses(): ServiceBlockingStatus[] {
      return stoppedRows(this.visibleStatuses);
    },

    verdictClass(): string {
      return this.stoppedStatuses.length > 0 ? 'verdict--blocked' : 'verdict--clear';
    },

    kpis(): (KpiTile & { count: number })[] {
      const tally = new Map<BlockingGateState, number>();
      this.visibleStatuses.forEach((status) => {
        const state = this.state(status);
        tally.set(state, (tally.get(state) ?? 0) + 1);
      });

      return KPI_TILES.map((tile) => ({
        ...tile,
        count: tile.states.reduce((sum, state) => sum + (tally.get(state) ?? 0), 0),
      }));
    },
  },

  mounted() {
    this.fetchStatuses();

    if (this.monitorMode) {
      // Kiosk: show every row (no pagination footer to reach), rotate the line
      // on a one-shot timer, and tick a clock for the live age readout. The
      // clock does no I/O, so a throttled tick costs nothing.
      this.pagination.rowsPerPage = 0;
      this.scheduleSwitch();
      this.clockTimer = window.setInterval(() => {
        this.now = Date.now();
      }, 10_000);
      // The wall needs its OWN data refresh now that rotating no longer fetches.
      // Not gated on document.hidden, unlike the desk below: a kiosk tab can be
      // reported hidden for reasons nobody is present to notice — a screensaver,
      // a compositor decision — and a wall that quietly stopped refreshing would
      // keep showing a confident board of stale verdicts. The age readout is the
      // only thing that would give it away, from across a room.
      this.refreshTimer = window.setInterval(() => {
        void this.fetchStatuses(true);
      }, AUTO_REFRESH_MS);
    } else {
      this.refreshTimer = window.setInterval(() => {
        // Skip the tick while the tab is hidden — no point querying a dashboard
        // nobody is looking at. The interval itself is free.
        if (!document.hidden) {
          void this.fetchStatuses(true);
        }
      }, AUTO_REFRESH_MS);
    }
  },

  beforeUnmount() {
    // Vue Router unmounts this component on route change (no <keep-alive> in the
    // layouts), so without this a monitor visit would leave its rotation and
    // clock behind. Every timer this component can own is cleared here.
    if (this.refreshTimer !== null) window.clearInterval(this.refreshTimer);
    if (this.switchTimer !== null) window.clearTimeout(this.switchTimer);
    if (this.retryTimer !== null) window.clearTimeout(this.retryTimer);
    if (this.clockTimer !== null) window.clearInterval(this.clockTimer);
  },

  methods: {
    /**
     * @param silent - background refresh: keeps the current table on screen
     *   instead of swapping in the loading state, and keeps the last good data
     *   if the request fails.
     */
    async fetchStatuses(silent = false): Promise<void> {
      // Never let a tick overlap an in-flight request
      if (this.loading || this.refreshing) {
        return;
      }

      if (silent) {
        this.refreshing = true;
      } else {
        this.loading = true;
        this.error = null;
      }

      try {
        // Both release lines in one request; the estate merge and the split by
        // track happen in `statuses`, so the switch needs no round trip.
        this.reported = await deployBlockingTestsPrometheusService.getBlockingStatuses(this.environment);
        this.lastFetchedAt = new Date();
        this.now = Date.now();
        this.error = null;
        // A recovered monitor fetch clears the reconnecting state and resets the
        // backoff, so the next outage starts from the short delay again.
        if (this.monitorMode) {
          this.retrying = false;
          this.retryStep = 0;
          if (this.retryTimer !== null) {
            window.clearTimeout(this.retryTimer);
            this.retryTimer = null;
          }
        }
      } catch (err) {
        logger.error('[DeploymentStatusPage] Failed to load gate metrics:', err);
        if (this.monitorMode) {
          // The wall never blanks and never raises a banner: keep the last good
          // data, show "reconnecting…" beside the age, and arm a bounded retry.
          this.retrying = true;
          this.scheduleRetry();
        } else {
          this.error = silent
            ? 'Auto-refresh could not reach Prometheus. Showing the last successful result.'
            : 'Could not reach Prometheus. Please try again.';
          // A failed background refresh must not blank a table someone is reading.
          // The "updated" timestamp still shows when the data was actually current.
          if (!silent) {
            this.reported = [];
          }
        }
      } finally {
        this.loading = false;
        this.refreshing = false;
      }
    },

    /**
     * Arm the next line switch (monitor only).
     *
     * A fresh one-shot timer per cycle, always cleared first, so exactly one is
     * ever outstanding. Measuring each cycle from now — rather than a repeating
     * interval — is what keeps the rotation honest over a long uptime: a tick the
     * browser delivered late shifts that one switch and nothing after it.
     */
    scheduleSwitch(): void {
      if (this.switchTimer !== null) {
        window.clearTimeout(this.switchTimer);
      }
      this.switchTimer = window.setTimeout(() => {
        this.switchTimer = null;
        this.switchLine();
      }, LINE_ROTATION_MS);
    },

    /**
     * Show the other release line (monitor only).
     *
     * Synchronous, and no fetch: one query already holds both lines, so this is a
     * re-render of data the page has. That is what makes a 30-second cycle
     * affordable, and it also removes the failure mode the old version had to
     * work around — a switch can no longer stall on the network, because it does
     * not touch it. The data behind both lines ages together on the refresh
     * timer, and the header's age readout describes it.
     */
    switchLine(): void {
      const index = RELEASE_TRACKS.indexOf(this.track);
      this.track = RELEASE_TRACKS[(index + 1) % RELEASE_TRACKS.length] as ReleaseTrack;
      this.scheduleSwitch();
    },

    /**
     * Arm the next retry at the current backoff step (monitor only).
     *
     * The step advances to the ceiling and stays there; any success resets it.
     * Only one retry is ever outstanding, so a run of failures cannot stack
     * timers up.
     */
    scheduleRetry(): void {
      if (this.retryTimer !== null) {
        window.clearTimeout(this.retryTimer);
      }
      const delay = RETRY_BACKOFF_MS[Math.min(this.retryStep, RETRY_BACKOFF_MS.length - 1)];
      this.retryStep = Math.min(this.retryStep + 1, RETRY_BACKOFF_MS.length - 1);
      this.retryTimer = window.setTimeout(() => {
        this.retryTimer = null;
        void this.fetchStatuses(true);
      }, delay);
    },

    state(status: ServiceBlockingStatus): BlockingGateState {
      return gateState(status);
    },

    /** Label, icon and hover explanation for a row's state. */
    info(state: BlockingGateState): GateStatePresentation {
      return GATE_STATES[state];
    },

    /**
     * Whether this row needs no attention at all: both columns are green.
     *
     * Defers to rowTone rather than re-listing the states that count, which is
     * how it drifted out of step with the rail and the dot — it still named only
     * 'failed' and 'unverified', so a NOT DEPLOYED row was dimmed on the wall
     * while its rail was red. One definition, three consumers.
     *
     * Drives the quieter type on the wall. Computed here rather than with a CSS
     * `:has()` on the deployment pill because the kiosk's browser version is
     * unknown and unreachable — `:has()` needs Chrome 105+, and a selector that
     * silently does not match would leave the wall uniformly bold with no way to
     * tell from the office.
     *
     * A row that PASSED its tests but failed to roll out is deliberately not
     * settled: it is the exact row this split exists to surface, and quietening
     * it would hide it behind the services that are fine.
     */
    settled(status: ServiceBlockingStatus): boolean {
      return rowTone(status) === 'good';
    },

    /**
     * How alarming this row is overall — the worse of its two columns.
     *
     * The one signal a reader gets per row, so it cannot be the test verdict
     * alone: that is how auth-service ended up under a green dot with a failed
     * deployment beside it.
     */
    tone(status: ServiceBlockingStatus): GateTone {
      return rowTone(status);
    },

    /** The row's rollout verdict — independent of its test verdict. */
    deployState(status: ServiceBlockingStatus): DeploymentState {
      return deploymentState(status);
    },

    /** Label, icon and hover explanation for a row's rollout verdict. */
    deployInfo(status: ServiceBlockingStatus): GateStatePresentation {
      return DEPLOYMENT_STATES[this.deployState(status)];
    },

    /**
     * WHY nothing shipped, named as specifically as the data allows, or null when
     * there is nothing to say.
     *
     * Three sources, most trustworthy first, and never a guess of our own:
     *
     *  1. `failed_stage` — the producer's closed vocabulary (DEVO-150). This is
     *     the one that answers "was it the deployment, or something before it?":
     *     only `rollout` means the Helm upgrade itself failed. Preferred because
     *     it cannot go stale when a caller renames its jobs.
     *  2. `blocked_by` — finer-grained (it names the individual gate JOB) but
     *     free text, so it goes through the maintained allow-list. Appended to
     *     the stage where both exist, since "failed at a database migration
     *     (apply-migration-eu)" beats either half alone.
     *  3. Nothing — and then this renders nothing rather than inventing a cause.
     *
     * An unrecognised blocked_by value is still SHOWN, marked as unrecognised: an
     * unknown reason is information, and hiding it would leave the unverified
     * pill with nothing behind it.
     */
    deployReason(status: ServiceBlockingStatus): string | null {
      const state = this.deployState(status);
      if (state === 'deployed' || state === 'no-metrics') return null;

      const blockedBy = (status.blockedBy ?? '').trim();
      const classes = blockedByClasses(blockedBy);
      // The specific job, where we can name it honestly. Skipped for
      // 'did-not-run', which is a collector marker rather than a job.
      const job =
        !blockedBy || blockedBy === 'did-not-run' || blockedBy === 'unknown'
          ? null
          : classes.has('unknown-value')
            ? `${blockedBy} (unrecognised step)`
            : blockedBy;

      const stage = status.failedStage;
      if (stage && stage !== 'none' && stage in DEPLOY_STAGE_REASON) {
        const reason = DEPLOY_STAGE_REASON[stage as keyof typeof DEPLOY_STAGE_REASON];
        return job ? `${reason} (${job})` : reason;
      }

      // No stage label — a series pushed before DEVO-150. Say what the older
      // labels can carry, and no more.
      if (status.deployResult === 'failure') return 'the Helm rollout itself failed';
      if (blockedBy === 'unknown') return 'blocked, reason not reported by CI';
      // A test-gate block gets NO reason line. The pill already says BLOCKED and
      // the Test status column beside it names the failing suite — repeating
      // "blocked by the test gate" under the pill only spent a line saying so
      // twice, and on the wall those lines are what cost the board its rows.
      if (state === 'blocked') return null;
      if (!job) return null;
      return classes.has('deploy-step') ? `failed at ${job}` : `blocked by ${job}`;
    },

    /** Inline warning for verdicts that look green but should not be trusted. */
    caveat(status: ServiceBlockingStatus): string | null {
      const state = this.state(status);
      // Guarded on `passed`: 'no-tests' no longer implies a green verdict now
      // that a gate blocked for a NON-test reason keeps its real test state, and
      // claiming "gate reports success" about a blocked row would be false. The
      // blocked variant is handled further down.
      if (state === 'no-tests' && status.passed) {
        return 'Gate reports success but ran no blocking tests — not a genuine pass.';
      }
      if (state === 'did-not-run' || state === 'incomplete') {
        if (status.blockedBy === 'did-not-run' && status.hasStatus) {
          // The one case a reader cannot possibly infer from the row: there IS a
          // green verdict in the window, and it is not this run's.
          return 'The latest run never reached a verdict. The verdict still in the read window is from an earlier run and does not describe this one.';
        }
        return state === 'incomplete'
          ? 'The run was cancelled before the gate reached a verdict — the counts are real, the verdict is missing.'
          : 'The gate is configured but reached no verdict and measured nothing — unverified, not passing.';
      }
      // A green test verdict on a blocked row no longer gets a caveat line
      // pointing at the Deployment column: that cell names the stage which
      // stopped the deploy directly under its pill (see deployReason), so a
      // second line saying "look next door" was pure noise on desk and wall.
      //
      // The one case that DOES still need words is the contradiction: a gate
      // that refused a run which then reported a successful rollout. The two
      // verdicts genuinely disagree, and hiding that behind either of them is
      // how a producer inconsistency stays unnoticed.
      if (
        !status.passed &&
        (state === 'passing' || state === 'no-tests') &&
        this.deployState(status) === 'deployed'
      ) {
        return 'The gate refused this run, but a successful rollout was reported for it — the two disagree. Not the all-clear it looks like.';
      }
      if (status.passed && status.counts.failed > 0) {
        return `Gate reports success despite ${status.counts.failed} failed ${
          status.counts.failed === 1 ? 'test' : 'tests'
        }.`;
      }
      return null;
    },

    displayName(service: string): string {
      return serviceDisplayName(service);
    },

    webKey(service: string): string | null {
      return serviceWebKey(service);
    },

    runLink(status: ServiceBlockingStatus): string | null {
      return runUrl(status);
    },

    rowKey(status: ServiceBlockingStatus): string {
      // `track` belongs in the key even though the table shows one line at a
      // time: it is the row IDENTITY, and the DOM id is what focusRow() scrolls
      // to. Two lines' rows for one service must never collide.
      return `gate-${status.service}-${status.environment}-${status.track}`.replace(
        /[^a-zA-Z0-9-]/g,
        '-'
      );
    },

    /** Whether this row has a push timestamp at all, as opposed to how old it is. */
    hasReported(status: ServiceBlockingStatus): boolean {
      return status.hasMetrics && status.finishedAt.getTime() > 0;
    },

    /**
     * What a cell says when the service published no measurement at all.
     *
     * Never a bare dash. A dash leaves the reader deciding between "the number
     * is missing" and "the number is zero", and for this board those are
     * opposite findings — the collector deliberately refuses to publish 0
     * passed across 0 suites, because that is the shape of an empty artifact
     * download rather than a measurement of anything.
     *
     * Matches the Reported column, which has always said "never" instead of
     * rendering an empty chip.
     */
    absent(): { text: string; explain: string } {
      return {
        text: 'no data',
        explain:
          'This service published no blocking-test metrics for this line, so there is no count to show — which is not the same as a count of zero.',
      };
    },

    /**
     * What the Version cell says when no image tag was published.
     *
     * Two different absences, and the difference is the whole point: a service
     * that reports nothing has no version because nothing was measured, while a
     * service whose run was STOPPED has no version because the job that tags one
     * is gated behind the test gate and never ran. The second is a direct
     * consequence of the red beside it, and saying so stops it reading as a
     * missing field.
     */
    versionAbsent(status: ServiceBlockingStatus): { text: string; explain: string } {
      if (!status.hasMetrics) return this.absent();
      if (STOPPED_DEPLOYMENT_STATES.includes(this.deployState(status))) {
        return {
          text: 'not built',
          explain:
            'Nothing was tagged for this run. The version job runs after the test gate, so a run that never got past the gate publishes no version — the missing value here is the same event as the red beside it.',
        };
      }
      return {
        text: 'no version',
        explain: 'This run reported no image tag.',
      };
    },

    /** Both filters at once — what the empty board offers as the way back. */
    clearFilters(): void {
      this.search = '';
      this.stateFilter = null;
    },

    toggleStateFilter(tile: KpiTile): void {
      this.stateFilter = this.stateFilter?.label === tile.label ? null : tile;
    },

    focusRow(status: ServiceBlockingStatus): void {
      const key = this.rowKey(status);
      this.stateFilter = null;
      this.$nextTick(() => {
        document.getElementById(key)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        this.flashed = key;
        window.setTimeout(() => {
          if (this.flashed === key) this.flashed = null;
        }, 1600);
      });
    },

    relativeAge(value: Date): string {
      if (!value || value.getTime() === 0) return 'never';
      const minutes = Math.round((Date.now() - value.getTime()) / 60_000);
      if (minutes < 1) return 'just now';
      if (minutes < 60) return `${minutes}m ago`;
      const hours = Math.round(minutes / 60);
      if (hours < 24) return `${hours}h ago`;
      return `${Math.round(hours / 24)}d ago`;
    },

    formatDateTime(value: Date): string {
      return date.formatDate(value, 'MMM D, YYYY HH:mm');
    },
  },
});
</script>

